/**
 * osm-supplement-provider.js
 * ─────────────────────────────────────────────────────────────────────────────
 * OSMSupplementProvider — Interface and default implementation for loading
 * supplemental environmental visual data (buildings, vegetation, water).
 *
 * ARCHITECTURAL PURPOSE
 * ─────────────────────
 * The simulation backend contains no building, vegetation, or water data.
 * These are visual-only assets. Their data source may be:
 *   - Empty arrays (Phase 0–4, default)
 *   - Local JSON files generated by an offline OSM import tool (future)
 *   - Procedurally generated data (possible future option)
 *
 * This class provides a stable interface that MapLayerManager depends on.
 * The renderer classes receive data from this provider without knowing where
 * the data came from. Swapping the data source means changing only this class.
 *
 * PRODUCTION RULE
 * ───────────────
 * The production renderer must NEVER depend on a live Overpass API request.
 * This provider may only load data from local files or cached data.
 * If an OSM import is needed, it is performed by a separate offline tool
 * that writes local JSON files. This provider reads those local files.
 *
 * DATA FORMATS
 * ────────────
 * All coordinates in loaded data are simulation-space metres { x, z }.
 * The OSM import tool is responsible for transforming geographic coordinates
 * to simulation space during the import step.
 *
 * BUILDINGS DATA FORMAT (buildings.json)
 * {
 *   buildings: [{
 *     id: string,
 *     footprint: { x, z }[],    -- polygon vertices in sim metres
 *     levels: number,            -- number of storeys
 *     heightM: number,           -- height in metres
 *     type: string               -- 'residential' | 'commercial' | 'industrial' | 'default'
 *   }]
 * }
 *
 * VEGETATION DATA FORMAT (vegetation.json)
 * {
 *   areas: [{
 *     id: string,
 *     polygon: { x, z }[],      -- park/green area polygon
 *     type: string               -- 'park' | 'grass' | 'meadow'
 *   }],
 *   trees: [{
 *     id: string,
 *     pos: { x, z },             -- single tree position
 *     radiusM: number            -- canopy radius in metres
 *   }]
 * }
 *
 * WATER DATA FORMAT (water.json)
 * {
 *   bodies: [{
 *     id: string,
 *     polygon: { x, z }[]       -- water body polygon
 *   }],
 *   ways: [{
 *     id: string,
 *     polyline: { x, z }[],     -- waterway centreline
 *     type: string,              -- 'river' | 'stream'
 *     widthM: number
 *   }]
 * }
 * ─────────────────────────────────────────────────────────────────────────────
 */

'use strict';

class OSMSupplementProvider {
  constructor() {
    this._buildings  = null;
    this._vegetation = null;
    this._water      = null;
    this._loaded     = false;
  }

  // ─── Data Loading ──────────────────────────────────────────────────────────

  /**
   * Loads all supplemental data files.
   * Gracefully handles missing files — returns empty datasets on 404 or error.
   *
   * @param {object} [options]
   * @param {string} [options.buildingsUrl='/static/data/static/buildings.json']
   * @param {string} [options.vegetationUrl='/static/data/static/vegetation.json']
   * @param {string} [options.waterUrl='/static/data/static/water.json']
   * @returns {Promise<void>}
   */
  async load(options = {}) {
    const {
      buildingsUrl  = '/static/data/static/buildings.json',
      vegetationUrl = '/static/data/static/vegetation.json',
      waterUrl      = '/static/data/static/water.json',
    } = options;

    const [buildings, vegetation, water] = await Promise.all([
      this._fetchJson(buildingsUrl,  { buildings: [] }),
      this._fetchJson(vegetationUrl, { areas: [], trees: [] }),
      this._fetchJson(waterUrl,      { bodies: [], ways: [] }),
    ]);

    this._buildings  = buildings;
    this._vegetation = vegetation;
    this._water      = water;
    this._loaded     = true;

    console.info(
      `[OSMSupplementProvider] Loaded: ` +
      `${(buildings.buildings  || []).length} buildings, ` +
      `${(vegetation.areas     || []).length} vegetation areas, ` +
      `${(vegetation.trees     || []).length} trees, ` +
      `${(water.bodies         || []).length} water bodies`
    );
  }

  // ─── Data Accessors ────────────────────────────────────────────────────────

  /**
   * Returns the loaded buildings dataset.
   * Returns an empty dataset if not yet loaded.
   *
   * @returns {{ buildings: object[] }}
   */
  getBuildings() {
    return this._buildings || { buildings: [] };
  }

  /**
   * Returns the loaded vegetation dataset.
   * Returns an empty dataset if not yet loaded.
   *
   * @returns {{ areas: object[], trees: object[] }}
   */
  getVegetation() {
    return this._vegetation || { areas: [], trees: [] };
  }

  /**
   * Returns the loaded water dataset.
   * Returns an empty dataset if not yet loaded.
   *
   * @returns {{ bodies: object[], ways: object[] }}
   */
  getWater() {
    return this._water || { bodies: [], ways: [] };
  }

  /** @returns {boolean} true if load() has completed */
  isLoaded() {
    return this._loaded;
  }

  // ─── Private ───────────────────────────────────────────────────────────────

  /**
   * Fetches a JSON file from the given URL.
   * Returns `fallback` on any error (404, network failure, parse error).
   *
   * @param {string} url
   * @param {*} fallback
   * @returns {Promise<*>}
   */
  async _fetchJson(url, fallback) {
    try {
      const response = await fetch(url);
      if (!response.ok) {
        // 404 or other HTTP error — data file not yet generated
        console.info(`[OSMSupplementProvider] ${url} not found (${response.status}) — using empty dataset`);
        return fallback;
      }
      return await response.json();
    } catch (err) {
      console.info(`[OSMSupplementProvider] ${url} load failed — using empty dataset`);
      return fallback;
    }
  }
}

window.OSMSupplementProvider = OSMSupplementProvider;
